const reserveListingStock = `-- name: ReserveListingStock :execrows
UPDATE listings SET quantity_available = quantity_available - $2
WHERE id = $1 AND quantity_available >= $2
`

type ReserveListingStockParams struct {
	ID                uuid.UUID
	QuantityAvailable int32
}

// Atomically decrements stock only while enough remains. Zero affected rows is
// ErrInsufficientStock; the caller's transaction rolls back.
func (q *Queries) ReserveListingStock(ctx context.Context, arg ReserveListingStockParams) (int64, error) {
	result, err := q.db.Exec(ctx, reserveListingStock, arg.ID, arg.QuantityAvailable)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const restoreListingStock = `-- name: RestoreListingStock :exec
UPDATE listings SET quantity_available = quantity_available + $2 WHERE id = $1
`

type RestoreListingStockParams struct {
	ID                uuid.UUID
	QuantityAvailable int32
}

// The exact inverse of a reservation, from the stored order items rather than
// the request, so a restored checkout can never drift.
func (q *Queries) RestoreListingStock(ctx context.Context, arg RestoreListingStockParams) error {
	_, err := q.db.Exec(ctx, restoreListingStock, arg.ID, arg.QuantityAvailable)
	return err
}

