func (q *Queries) SetOrderDeliveredAt(ctx context.Context, arg SetOrderDeliveredAtParams) error {
	_, err := q.db.Exec(ctx, setOrderDeliveredAt, arg.ID, arg.DeliveredAt, arg.AutoCompleteAt)
	return err
}

