const setOrderStatus = `-- name: SetOrderStatus :one
UPDATE orders SET status = $2 WHERE id = $1 AND status = $3
RETURNING id, checkout_id, buyer_id, seller_id, status, escrow_state, subtotal_pesewas, delivery_fee_pesewas, base_pesewas, commission_rate_bps, commission_pesewas, refunded_pesewas, delivery_method, delivery_address, delivery_region, delivery_district, recipient_name, recipient_phone, tracking_ref, paid_at, accepted_at, shipped_at, delivered_at, completed_at, cancelled_at, auto_complete_at, created_at, updated_at
`

type SetOrderStatusParams struct {
	ID       uuid.UUID
	Status   string
	Status_2 string
}

// Transition's status write. Only the target status's timestamp column moves;
// escrow_state is the caller's to set, because it depends on why the order
// moved. Returns no row when the current status differs, which Transition
// treats as a lost race rather than a silent no-op.
func (q *Queries) SetOrderStatus(ctx context.Context, arg SetOrderStatusParams) (Order, error) {
	row := q.db.QueryRow(ctx, setOrderStatus, arg.ID, arg.Status, arg.Status_2)
	var i Order
	err := row.Scan(
		&i.ID,
		&i.CheckoutID,
		&i.BuyerID,
		&i.SellerID,
		&i.Status,
		&i.EscrowState,
		&i.SubtotalPesewas,
		&i.DeliveryFeePesewas,
		&i.BasePesewas,
		&i.CommissionRateBps,
		&i.CommissionPesewas,
		&i.RefundedPesewas,
		&i.DeliveryMethod,
		&i.DeliveryAddress,
		&i.DeliveryRegion,
		&i.DeliveryDistrict,
		&i.RecipientName,
		&i.RecipientPhone,
		&i.TrackingRef,
		&i.PaidAt,
		&i.AcceptedAt,
		&i.ShippedAt,
		&i.DeliveredAt,
		&i.CompletedAt,
		&i.CancelledAt,
		&i.AutoCompleteAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
